var parser = new SelectorParser();

// Parse a simple selector
var selectorList = parser.Parse("div.main-content");

// Parse a complex selector with pseudo-classes
var complexSelector = parser.Parse("nav > ul li:nth-child(2n+1):hover");

// Parse multiple selectors
var multipleSelectors = parser.Parse("h1, h2, h3");

// Parse functional selectors
var functionalSelector = parser.Parse(":not(.hidden):is(.visible, .shown)");

var parser = new SelectorParser();

// Basic selector parsing
var basic = parser.Parse("p.intro");

// Complex selector with multiple combinators
var complex = parser.Parse("article > header + p:first-of-type");

// Multiple selectors
var multiple = parser.Parse("h1, h2, h3, h4, h5, h6");

// Advanced functional selectors
var advanced = parser.Parse(":is(section, article) :where(h1, h2):not(.hidden)");

// Attribute selectors with various matchers
var attributes = parser.Parse("[data-state='active'][class*='btn']:not([disabled])");
